export async function fetchMessage(req, res, store) {
  const principal = req.auth; // Populated only after token verification
  if (!principal?.userId || !principal?.tenantId) {
    return res.status(401).json({ error: "authentication required" });
  }

  const message = await store.getMessage(req.params.messageId);
  if (!message) {
    return res.status(404).json({ error: "message not found" });
  }

  if (message.tenantId !== principal.tenantId) {
    return res.status(404).json({ error: "message not found" });
  }

  const isSender = message.senderId === principal.userId;
  const hasReadGrant = await store.hasChannelPermission({
    channelId: message.channelId,
    userId: principal.userId,
    permission: "message:read"
  });

  if (!isSender && !hasReadGrant) {
    return res.status(403).json({ error: "message access denied" });
  }

  return res.status(200).json({ message });
}

function decodeClaims(token) {
  const parts = token.split(".");
  if (parts.length !== 3) throw new Error("malformed token");
  return JSON.parse(Buffer.from(parts[1], "base64url").toString("utf8"));
}

export async function subscribe(req, res, broker) {
  const authorization = req.headers.authorization || "";
  if (!authorization.startsWith("Bearer ")) {
    return res.status(401).json({ error: "missing bearer token" });
  }

  let claims;
  try {
    claims = decodeClaims(authorization.slice(7));
  } catch {
    return res.status(401).json({ error: "invalid token" });
  }

  if (!claims.sub || !claims.permissions?.includes("subscribe")) {
    return res.status(403).json({ error: "subscription denied" });
  }

  await broker.subscribe(claims.sub, req.body.channel);
  return res.status(200).json({ subscribed: true });
}

export async function publishToTopic(req, res, broker) {
  const { tenantId } = req.auth; // Set by verified authentication middleware
  const topic = req.body.topic;

  if (!topic.startsWith(`tenant-${tenantId}`)) {
    return res.status(403).json({ error: "topic access denied" });
  }

  await broker.publish(topic, req.body.message);
  return res.status(202).json({ accepted: true });
}
